&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;Current PT license in the state of practice &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;Minimum 1–2 years of experience (home health experience preferred) &lt;/span&gt;&lt;/li&gt;
