&lt;ul style=&quot;margin-top: 0in; margin-bottom: 0in;&quot; type=&quot;disc&quot;&gt;
&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;You value autonomy and thrive in a field-based environment &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;You’re passionate about patient independence and functional outcomes &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;You build strong, trusting relationships with patients and families &lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;You bring both clinical excellence and compassionate care to every visit &lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&lt;span style=&quot;font-weight: bold; font-family: &#39;times new roman&#39;, times, serif; font-size: 14pt;&quot;&gt;What We Offer&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;margin: 0in; font-family: &#39;Times New Roman&#39;; font-size: 12.0pt;&quot;&gt;&lt;span style=&quot;font-weight: bold; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;Health &amp;amp; Wellness&lt;/span&gt;&lt;/p&gt;
&lt;ul style=&quot;margin-top: 0in; margin-bottom: 0in;&quot; type=&quot;disc&quot;&gt;
&lt;li style=&quot;margin-top: 0px; margin-bottom: 0px; vertical-align: middle; font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;&lt;span style=&quot;font-family: &#39;times new roman&#39;, times, serif; font-size: 12pt;&quot;&gt;Medical, Dental &amp;amp; Vision coverage &lt;/span&gt;&lt;/li&gt;
